// authzRec 是一份限时一次性代转授权的落盘状态。授权在创建时绑定藏品
// 当时的持有版本（GrantVer）；持有关系后续无论怎样变化，授权都不会
// 恢复或改变。
type authzRec struct {
	ID        string    `json:"id"`
